\section{Preliminaries}

\begin{lemma}[gcd against a prime]\label{lem:gcdprime}
For a prime $p$ and any $x$, $\gcd(x,p)=p$ if $p\mid x$ and $\gcd(x,p)=1$ otherwise.
\end{lemma}

\begin{proof}
$\gcd(x,p)$ divides $p$, hence is $1$ or $p$; it equals $p$ exactly when $p\mid x$.
\end{proof}

\begin{lemma}[coprime split]\label{lem:split}
If $\gcd(p,q)=1$ then $\gcd(x,pq)=\gcd(x,p)\gcd(x,q)$ for all $x$.
\end{lemma}

Consequently, for a semiprime $N=pq$ the value $\gcd(x,N)$ lies in $\{1,p,q,pq\}$ and the residues below $N$ split into four cells according to which primes divide $x$.

\begin{lemma}[cell sizes]\label{lem:cells}
Let $N=pq$ with $p\neq q$ prime. Among $0\le x<N$ there are exactly $q$ multiples of $p$, exactly $p$ multiples of $q$, exactly one common multiple (namely $x=0$), hence exactly $q-1$ residues divisible by $p$ only, $p-1$ divisible by $q$ only, and $(p-1)(q-1)=\varphi(N)$ divisible by neither.
\end{lemma}

\begin{proof}
The multiples of $p$ below $pq$ are the image of $\{0,\dots,q-1\}$ under the injection $i\mapsto pi$; symmetrically for $q$. A common multiple is divisible by $pq$ by coprimality, and the only such residue below $pq$ is $0$. Inclusion--exclusion gives the remaining counts, and $\varphi(pq)=\varphi(p)\varphi(q)$.
\end{proof}

\section{Witness $W_1$: the gcd-sum and the reach chain}

\begin{definition}
Pillai's arithmetical function is $M_1(N)=\sum_{x=0}^{N-1}\gcd(x,N)$. Its definition route is a full scan of the $N$ residues, costing $\Theta(N)$ gcd computations.
\end{definition}

\begin{theorem}[closed form]\label{thm:pillai}
Let $p\neq q$ be primes and $N=pq$. Then
\[
M_1(N)+2(p+q)=4N+1,\qquad\text{i.e.}\qquad M_1(N)=4N-2s+1,\quad s=p+q.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemmas~\ref{lem:gcdprime}--\ref{lem:split},
\[
\gcd(x,N)=1+(p-1)[p\mid x]+(q-1)[q\mid x]+(p-1)(q-1)[p\mid x][q\mid x],
\]
verified by checking the four divisibility cases. Summing over $0\le x<N$ and applying Lemma~\ref{lem:cells} to each term gives
$M_1(N)=pq+(p-1)q+(q-1)p+(p-1)(q-1)=4pq-2(p+q)+1$.
\end{proof}

The identity is stated additively so that it holds in the natural numbers without truncated subtraction.

\begin{example}
$N=15$: $M_1=45$. $N=35$: $M_1=117$. $N=143=11\cdot13$: $M_1=572-48+1=525$.
\end{example}

\begin{theorem}[rigidity of the pair]\label{thm:rigid}
If $p+q=p'+q'$, $pq=p'q'$, $p\le q$ and $p'\le q'$, then $p=p'$ and $q=q'$.
\end{theorem}

\begin{proof}[Proof sketch]
Over $\mathbb{Z}$, $(q-p)^2=(p+q)^2-4pq=(p'+q')^2-4p'q'=(q'-p')^2$. Both differences are non-negative, so $q-p=q'-p'$; with the equality of sums this gives the claim.
\end{proof}

\begin{corollary}[explicit recovery]\label{cor:recover}
For a semiprime, $s=p+q=\bigl(4N+1-M_1(N)\bigr)/2$, and $(N,s)$ determines $\{p,q\}$.
\end{corollary}

\begin{theorem}[$W_1$ reaches the factors]
If $N=pq=p'q'$ with $p\le q$, $p'\le q'$ all prime and $p\ne q$, $p'\ne q'$, and $M_1(pq)=M_1(p'q')$, then $p=p'$ and $q=q'$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:pillai} on both sides forces $p+q=p'+q'$; Theorem~\ref{thm:rigid} concludes.
\end{proof}

\begin{remark}[honest caveat]
``$N$ together with a witness determines $\{p,q\}$'' is by itself vacuous, since unique factorisation already determines $\{p,q\}$ from $N$. The substance of the reach chain is constructive: Corollary~\ref{cor:recover} recovers $s$ from $(N,M_1)$ in $O(1)$ arithmetic operations, and Theorem~\ref{thm:rigid} recovers the pair from $(N,s)$ by a square root. The chain therefore says that the only obstruction along this route is evaluating $M_1$.
\end{remark}

\begin{theorem}[equivalence with the totient]\label{thm:totient}
For a semiprime $N=pq$, $\;M_1(N)+1=2\varphi(N)+2N$.
\end{theorem}

\begin{proof}
$\varphi(N)=(p-1)(q-1)=N-s+1$, so $2\varphi(N)+2N=4N-2s+2=M_1(N)+1$ by Theorem~\ref{thm:pillai}.
\end{proof}

Thus $M_1$ and $\varphi$ are affinely equivalent on semiprimes: reading $M_1$ is exactly as informative, and by the classical equivalence between computing $\varphi$ of a semiprime and factoring it, exactly as hard, as reading $\varphi$.

\section{The entire class of local gcd-statistics}

\begin{definition}
For $f:\mathbb{N}\to\mathbb{N}$, the \emph{local gcd-statistic} is $S_f(N)=\sum_{x=0}^{N-1}f(\gcd(x,N))$. Taking $f=\mathrm{id}$ gives $W_1$; $f(d)=[d>1]$ counts non-units; $f(d)=d^2$ gives the gcd-square sum.
\end{definition}

\begin{theorem}[class-wide closed form]\label{thm:class}
For every $f$ and every semiprime $N=pq$ with $p\neq q$,
\[
S_f(N)=f(pq)+(q-1)f(p)+(p-1)f(q)+(p-1)(q-1)f(1).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition $\{0,\dots,N-1\}$ into the four cells of Lemma~\ref{lem:cells}. On each cell $\gcd(x,N)$ is constant with value $pq$, $p$, $q$, $1$ respectively, so the contribution of a cell is its size times $f$ of that value.
\end{proof}

\begin{corollary}
Every local gcd-statistic of a semiprime is a symmetric function of $\{p,q\}$ determined by $f(1),f(p),f(q),f(pq)$. No summand $f$ extracts anything finer than the unordered pair.
\end{corollary}

\begin{corollary}[information-free members]\label{cor:free}
Taking $f\equiv 1$ gives $S_f(N)=N$: a $\Theta(N)$ computation returning its input.
\end{corollary}

\begin{proof}
$1+(q-1)+(p-1)+(p-1)(q-1)=pq$.
\end{proof}

The class of gcd-local sums is therefore one witness with a parameter; improving the exponent cannot come from a cleverer summand, which only redistributes weights among four numbers.

\section{Witness $W_2$: exact cost of the zero-divisor scan}

\begin{definition}
The \emph{zero-divisor scan} walks $x=1,2,3,\dots$ and halts at the first \emph{hit}, i.e.\ the first $x$ with $\gcd(x,N)>1$.
\end{definition}

\begin{lemma}[hits are multiples]\label{lem:hit}
For $N=pq$ with $p,q$ prime, $\gcd(x,N)>1$ if and only if $p\mid x$ or $q\mid x$.
\end{lemma}

\begin{proof}
A gcd exceeding $1$ has a prime divisor $r$ dividing both $x$ and $pq$, so $r\in\{p,q\}$. Conversely if $p\mid x$ then $p\mid\gcd(x,N)$.
\end{proof}

\begin{theorem}[the exact cost]\label{thm:firsthit}
For $N=pq$ with $p,q$ prime, $\min(p,q)$ is the least element of $\{x>0:\gcd(x,N)>1\}$.
\end{theorem}

\begin{proof}
$\min(p,q)$ divides $N$ and exceeds $1$, hence is a hit. By Lemma~\ref{lem:hit} any positive hit is a multiple of $p$ or of $q$, hence at least $\min(p,q)$.
\end{proof}

\begin{proposition}\label{prop:cofac}
$\min(p,q)\cdot\max(p,q)=N$ and $N/\min(p,q)=\max(p,q)$.
\end{proposition}

\begin{theorem}[$W_2$ reaches the factors]\label{thm:w2reach}
If $pq=p'q'$ with $p\le q$, $p'\le q'$, $p$ prime, and $\min(p,q)=\min(p',q')$, then $p=p'$ and $q=q'$.
\end{theorem}

\begin{proof}
The hypothesis gives $p=p'$; cancelling $p$ in $pq=pq'$ gives $q=q'$.
\end{proof}

\begin{theorem}[hit count]\label{thm:hits}
For a semiprime $N=pq$ with $p\ne q$, exactly $p+q-1$ of the residues $0\le x<N$ are hits.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:hit} the hit set is the union of the multiples of $p$ and of $q$ below $N$; by Lemma~\ref{lem:cells} these have $q$ and $p$ elements and meet exactly in $\{0\}$.
\end{proof}

\begin{theorem}[miss count]
Exactly $\varphi(N)=(p-1)(q-1)$ residues below $N$ are coprime to $N$.
\end{theorem}

For a balanced semiprime the informative fraction of the scan plane is $\approx 2/\sqrt{N}$.

\begin{theorem}[random probing]\label{thm:random}
For a semiprime $N=pq$ with $p\ne q$, $\;\#\{\text{hits}\}\cdot\min(p,q)\le 2N$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:hits} the left side is $(p+q-1)\min(p,q)$; assuming $p\le q$ this is $(p+q-1)p\le 2pq$ because $p+q-1\le 2q$ for $p\ge 2$.
\end{proof}

\begin{corollary}
A uniformly random probe hits with probability at most $2/\min(p,q)$, so the expected number of probes before a hit is $\Omega(\min(p,q))$: randomisation meets the same wall as the deterministic scan.
\end{corollary}

\begin{theorem}[the $\sqrt{N}$ wall]\label{thm:wall}
If $p\le q\le 2p$ then $N=pq\le 2\min(p,q)^2$, i.e.\ the scan cost is at least $\sqrt{N/2}$.
\end{theorem}

\begin{proof}
$\min(p,q)=p$ and $pq\le p\cdot 2p=2p^2$.
\end{proof}

\begin{proposition}
Always $\min(p,q)^2\le pq$, so the scan cost never exceeds $\sqrt{N}$.
\end{proposition}

\section{Witnesses $W_3$ and $W_4$: two counting ladders}

\begin{definition}
An \emph{idempotent} modulo $N$ is a residue $x$ with $x^2\equiv x\pmod N$.
\end{definition}

\begin{theorem}[semiprime idempotent count]\label{thm:idem4}
For $N=pq$ with distinct primes there are exactly four idempotents modulo $N$.
\end{theorem}

\begin{proof}[Proof sketch]
In a field, $x(x-1)=0$ forces $x\in\{0,1\}$, so each of $\mathbb{Z}/p$ and $\mathbb{Z}/q$ carries two idempotents. Idempotents of a product ring are pairs of idempotents, and the Chinese Remainder isomorphism $\mathbb{Z}/pq\cong\mathbb{Z}/p\times\mathbb{Z}/q$ transports idempotents bijectively; the count is $2\cdot2=4$.
\end{proof}

The four idempotents are $0$, $1$ and a conjugate pair $e,1-e$. The trivial idempotent $x=0$ is one of the four and must not be excluded: it is exactly the Chinese-remainder choice $(0,0)$. For $N=15$ they are $0,1,6,10$; for $N=35$ they are $0,1,15,21$.

\begin{corollary}[the counter is constant]\label{cor:idemconst}
Any two semiprimes have the same idempotent count $4$; the $\Theta(N)$ route computing the count carries zero bits about the factorisation.
\end{corollary}

\begin{theorem}[idempotent ladder]\label{thm:idemladder}
For every $N>0$ the number of idempotents modulo $N$ is $2^{\omega(N)}$.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Local rigidity}: modulo $p^n$ the only idempotents are $0$ and $1$. If $x^2=x$ and $v\in[0,p^n)$ represents $x$, then $p^n\mid v(v-1)$; the prime $p$ cannot divide both $v$ and $v-1$, whose difference is $1$, so $p^n$ is coprime to one factor and divides the other, giving $v\equiv0$ or $v\equiv1$. \emph{Multiplicativity}: for coprime $a,b$ the Chinese Remainder isomorphism transports idempotents and idempotents of a product are pairs, so the count is multiplicative; $\omega$ is additive on coprime factors, and the base cases $N=1$ and $N=p^n$ match.
\end{proof}

\begin{example}
$N=105=3\cdot5\cdot7$ has $\omega=3$ and exactly eight idempotents; $N=49=7^2$ has $\omega=1$ and only the two trivial ones.
\end{example}

\begin{theorem}[square-root ladder]\label{thm:sqrtladder}
For every odd $N>0$, the equation $x^2\equiv1\pmod N$ has exactly $2^{\omega(N)}$ solutions.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Local rigidity}: modulo an odd prime power $p^n$, if $x^2=1$ with representative $v$ then $p^n\mid(v-1)(v+1)$; an odd prime cannot divide both $v-1$ and $v+1$, whose difference is $2$, so $x=\pm1$ and the local count is $2$. \emph{Multiplicativity}: square roots of unity multiply across a product of monoids and are transported by the Chinese Remainder isomorphism.
\end{proof}

\begin{remark}
Oddness is necessary: modulo $8$ the solutions of $x^2\equiv1$ are $1,3,5,7$, four of them, while $\omega(8)=1$. The prime $2$ is exactly where the ``difference is $2$'' step fails.
\end{remark}

\begin{corollary}\label{cor:sqrtconst}
An odd semiprime has exactly four square roots of unity, $\pm1$ and a conjugate pair obtained by a sign flip in one Chinese-remainder coordinate; hence this counter too is constant on the family.
\end{corollary}

\begin{example}
$N=35$: the roots are $1,6,29,34$. $N=45=3^2\cdot5$: four again --- the ladder is blind to exponents, as it must be, since $\omega(45)=2$.
\end{example}

\begin{theorem}[a nontrivial idempotent reveals a factor]\label{thm:idemreveal}
Let $N=pq$ with distinct primes and let $0<x<N$, $x\neq1$, satisfy $N\mid x(x-1)$. Then $\gcd(x,N)\in\{p,q\}$.
\end{theorem}

\begin{proof}[Proof sketch]
Each of $p,q$ divides $x(x-1)$, hence divides $x$ or $x-1$. Both dividing $x$ gives $N\mid x$, impossible for $0<x<N$; both dividing $x-1$ gives $N\mid x-1$, forcing $x=1$. So exactly one divides $x$, and it equals $\gcd(x,N)$, a divisor of $N$ strictly between $1$ and $N$.
\end{proof}

\begin{theorem}[a congruence of squares reveals a factor]\label{thm:sqrtreveal}
Let $N=pq$ with distinct primes, $y<x$ with $0<x-y<N$, $N\nmid(x+y)$ and $N\mid(x-y)(x+y)$. Then $\gcd(x-y,N)\in\{p,q\}$.
\end{theorem}

\begin{proof}[Proof sketch]
Each prime divides $x-y$ or $x+y$. Both dividing $x-y$ would force $N\mid x-y$, contradicting $0<x-y<N$; both dividing $x+y$ is excluded. So one prime goes to each side and $\gcd(x-y,N)$ is a proper nontrivial divisor of $N$.
\end{proof}

\begin{proposition}
If $g\in\{p,q\}$ then $N/g$ is the other prime.
\end{proposition}

Theorem~\ref{thm:sqrtreveal} is the reveal step shared by Fermat's difference of squares, the continued-fraction method, Pell-type relations and the quadratic sieve; it costs one gcd. For both local equations, the cardinality of the solution set is a function of $\omega(N)$ alone and hence blind, while any individual nontrivial solution is worth the full factorisation.

\section{No polylogarithmic route anywhere}

Define the route-cost set $\Cost(p,q)=\{pq,\ \min(p,q)\}$, containing the $\Theta(N)$ full scans of $W_1$ and $W_4$ and the exact cost of $W_2$.

\begin{lemma}\label{lem:floor}
For $p,q\ge1$, every $c\in\Cost(p,q)$ satisfies $\min(p,q)\le c$.
\end{lemma}

\begin{theorem}[the $\sqrt{N}$ floor]
If $p\le q\le 2p$ then every $c\in\Cost(p,q)$ satisfies $pq\le 2c^2$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:wall} gives $pq\le2\min(p,q)^2$ and Lemma~\ref{lem:floor} gives $\min(p,q)\le c$.
\end{proof}

\begin{lemma}[polynomials lose]\label{lem:polylose}
For every $d$ there is $K$ with $(m+1)^d<2^m$ for all $m\ge K$.
\end{lemma}

\begin{theorem}[no polylogarithmic route anywhere]\label{thm:verdict}
Fix $d\in\mathbb{N}$. There is a threshold $K$ such that for all $p,q\ge1$ with $p\le q\le2p$ and $pq\ge K$, and every $c\in\Cost(p,q)$,
\[
\bigl(\log_2(pq)\bigr)^d<c .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Put $N=pq$ and $k=\lfloor\log_2N\rfloor$, and let $K=2^{K_0+1}$ where $K_0$ is the constant of Lemma~\ref{lem:polylose} for degree $2d$, so that $k\ge K_0+1$. Two inequalities collide: geometrically $2^k\le N\le2p^2$, so $2^{k-1}\le p^2$; analytically $k^{2d}<2^{k-1}$. Chaining, $(k^d)^2<p^2$, hence $k^d<p=\min(p,q)\le c$ by Lemma~\ref{lem:floor}.
\end{proof}

\begin{remark}[honest boundary]
Theorem~\ref{thm:verdict} is a statement about \emph{definition routes} on balanced semiprimes, not a lower bound over all algorithms; the latter remains open. It shows that no tuning inside the family produces a $\mathrm{poly}(\log N)$ method, because the family's cheapest cost is on the $\sqrt{N}$ scale.
\end{remark}

\begin{theorem}[one plane]\label{thm:oneplane}
Let $N=pq=p'q'$ be factorisations into distinct primes with $p\le q$, $p'\le q'$. The following are equivalent:
(i) $M_1(pq)=M_1(p'q')$; (ii) $\min(p,q)=\min(p',q')$; (iii) $p+q=p'+q'$; (iv) $p=p'$ and $q=q'$.
Meanwhile the idempotent counter, and for odd moduli the square-root counter, return the constant $4$ in both cases and distinguish nothing.
\end{theorem}

\begin{proof}[Proof sketch]
(i)$\Leftrightarrow$(iii) by Theorem~\ref{thm:pillai} applied twice; (ii)$\Rightarrow$(iv) by Theorem~\ref{thm:w2reach} and conversely trivially; (iii)$\Leftrightarrow$(iv) by Theorem~\ref{thm:rigid}. The final clause is Corollaries~\ref{cor:idemconst} and~\ref{cor:sqrtconst}.
\end{proof}

\section{The black-box converse}

\begin{definition}
A \emph{strategy} is a function $S$ from finite lists of naturals to naturals: given the answers received so far, it names the next residue to probe. It has \emph{positive probes} if $S(\ell)>0$ for all $\ell$.
\end{definition}

\begin{definition}
The \emph{transcript} of $S$ on a hidden modulus $N$ after $T$ probes is $\tr_0=[\,]$ and $\tr_{n+1}=\tr_n \mathbin{+\!\!+} [\gcd(S(\tr_n),N)]$. The $n$-th \emph{null probe} is $S([1,\dots,1])$ with $n$ ones.
\end{definition}

\begin{lemma}[blindness]\label{lem:blind}
If $\gcd(\text{$n$-th null probe},N)=1$ for all $n<T$, then $\tr_T=[1,\dots,1]$ of length $T$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $T$: if the transcript so far is all ones, the next probe is by definition the corresponding null probe, whose answer is $1$.
\end{proof}

\begin{lemma}[small probes are blind]\label{lem:small}
If $p,q$ are primes and $0<x<\min(p,q)$ then $\gcd(x,pq)=1$.
\end{lemma}

\begin{proof}
By Lemma~\ref{lem:hit} a non-unit $x$ is a positive multiple of $p$ or $q$, hence at least $\min(p,q)$.
\end{proof}

\begin{theorem}[two indistinguishable semiprimes]\label{thm:blindpair}
For any strategy $S$ with positive probes and any budget $T$ there exist primes $p_1<q_1$ and $p_2<q_2$ with $p_1<p_2$ such that the transcripts of $S$ on $p_1q_1$ and on $p_2q_2$ after $T$ probes are both $[1,\dots,1]$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $B$ be the maximum of the first $T$ null probes, a finite quantity determined by $S$ alone. Choose primes $B<p_1<q_1<p_2<q_2$. For either modulus every null probe is a positive integer at most $B$, hence smaller than both prime factors, hence coprime to the modulus by Lemma~\ref{lem:small}; Lemma~\ref{lem:blind} applies.
\end{proof}

\begin{theorem}[no black-box algorithm factors]\label{thm:noalg}
Let $S$ be any adaptive strategy with positive probes, $T$ any budget, and $f$ any output rule mapping transcripts to pairs. Then there is a semiprime $N=pq$ with $p<q$ prime for which $f(\tr_T(S,N))\neq(p,q)$.
\end{theorem}

\begin{proof}
Take $p_1<q_1$, $p_2<q_2$ as in Theorem~\ref{thm:blindpair}; both transcripts equal the same list $L$, so $f$ returns the same pair. If $f(L)=(p_1,q_1)$ then $f(L)\neq(p_2,q_2)$ because $p_1<p_2$, and the second instance is answered wrongly; otherwise the first is.
\end{proof}

\begin{remark}
Theorem~\ref{thm:verdict} says the family's routes are expensive; Theorem~\ref{thm:noalg} says a gcd-probe algorithm is \emph{blind}. This is an information barrier rather than a cost barrier, and adaptivity does not evade it. The trade-off is the restricted access model: algorithms that perform arithmetic on $N$ itself are untouched.
\end{remark}

\section{Algorithms}

\textbf{Algorithm 1 (gcd-sum route).} Compute $M_1(N)$ by a full scan, set $s=(4N+1-M_1)/2$, solve $t^2=s^2-4N$ and output $\bigl((s-t)/2,(s+t)/2\bigr)$. Cost $\Theta(N)$ gcds plus $O(1)$ arithmetic; correctness by Theorem~\ref{thm:pillai}, Corollary~\ref{cor:recover} and Theorem~\ref{thm:rigid}.

\textbf{Algorithm 2 (zero-divisor scan).} For $x=2,3,\dots$ compute $g=\gcd(x,N)$ and halt when $g>1$; output $(g,N/g)$. Cost exactly $\min(p,q)$ iterations, between $\sqrt{N/2}$ and $\sqrt{N}$ for balanced semiprimes; correctness by Theorem~\ref{thm:firsthit} and Proposition~\ref{prop:cofac}.

\textbf{Algorithm 3 (witness reveal).} Given a nontrivial idempotent $x$, or a congruence of squares $x^2\equiv y^2$ with $x\not\equiv\pm y$, output $\gcd(x,N)$, respectively $\gcd(x-y,N)$, and the cofactor. Cost one gcd, $O(\log^2N)$ bit operations; correctness by Theorems~\ref{thm:idemreveal} and~\ref{thm:sqrtreveal}.

\section{Empirical notes}

The theorems were preceded by measurement, reported as observed. The gcd-sum and idempotent routes exhibited cost exponent $\alpha=1.000$ in $\mathrm{cost}\sim N^\alpha$, matching $\Theta(N)$ exactly. The zero-divisor scan matched $\mathrm{cost}=\min(p,q)$ in $60$ of $60$ trials, now Theorem~\ref{thm:firsthit} with no error term. The continued-fraction route measured $\alpha\approx0.398$, \emph{below} the naive $\tfrac12$: the period length of the continued fraction of $\sqrt{N}$ drifted as $\ell/\sqrt{N}\approx0.75,0.18,0.23$ across the tested sizes, so the period lags $\sqrt{N}$ rather than tracking it; no asymptotic claim is made. The reach chain held jointly at $100\%$, now Theorems~\ref{thm:rigid}, \ref{thm:w2reach} and~\ref{thm:oneplane}. Two process notes: a first run mis-sized its semiprimes by a bit parameter while $N$ carried twice that many bits, producing an intended $10^9$-operation stall caught before any claim; and the idempotent scan initially excluded $x=0$ and failed its own count-of-four assertion --- the trivial idempotent is one of the two Chinese-remainder sign choices, which is why Theorem~\ref{thm:idem4} reads $4$ and not $3$.

\section{Discussion and future directions}

The results delimit a family. Within the class of local gcd-statistics, the idempotent and square-root counters, and the zero-divisor scan, every route is super-polylogarithmic on balanced semiprimes, and every informative route delivers exactly $s=p+q$. Within the adaptive gcd-probe model no algorithm succeeds. Neither statement implies that factoring is hard: methods outside both the family and the access model, such as the number field sieve, are untouched.

Theorems~\ref{thm:idemladder} and~\ref{thm:sqrtladder} make precise a design principle. Local equations modulo $N$ have solution-set cardinalities given by Chinese-remainder multiplicativity, and local counts depend on the prime powers rather than on the primes; hence the global count is a function of the \emph{shape} of the factorisation, typically $2^{\omega(N)}$. Shape is not identity, so any invariant obtained by counting solutions of a local equation has an information ceiling. Conversely, individual solutions break the conjugation: a sign flip in one coordinate is exactly a choice of which prime goes on which side, and one gcd reads that choice off. A useful heuristic follows: before implementing a proposed witness, ask whether the quantity is a cardinality; if it is, and the equation is local, it is almost certainly an $\omega$-detector.

Open directions. (1) Extend the black-box converse to strategies allowed modular arithmetic, aiming at a model containing Pollard's $\rho$ and $p-1$. (2) Replace the balancedness hypothesis of Theorem~\ref{thm:verdict} by a sharp trade-off between imbalance and cost. (3) Explain the measured continued-fraction exponent theoretically: what is the typical period of $\sqrt{N}$ for a balanced semiprime? (4) Complete the square-root ladder at the prime $2$, where the count acquires a correction depending on the $2$-adic valuation. (5) Apply local rigidity plus the Chinese Remainder Theorem to $x^k=1$ and $x^k=x$, whose local counts involve $\gcd(k,p-1)$ and are therefore not pure powers of two; determine whether any such counter is genuinely informative on semiprimes, and at what cost. (6) Extract the optimal threshold in Theorem~\ref{thm:verdict}.

\section{Conclusion}

Four classical factor-revealing witnesses, and the two infinite families containing them, occupy one cost--information plane. The gcd-sum is an affine function of $N$ and $s=p+q$, equivalent to Euler's totient, as is every local gcd-statistic. The zero-divisor scan stops at exactly $\min(p,q)$, wastes exactly $\varphi(N)$ probes, and is not helped by randomisation. The idempotent count and the square-root-of-unity count are both exactly $2^{\omega(N)}$, hence constant on semiprimes and carrying zero factorisation information, while any single nontrivial witness of either kind yields a prime factor in one gcd. On balanced semiprimes every route in the family exceeds every fixed power of the bit length beyond an explicit threshold; and in the adaptive gcd-probe model the barrier is not cost but blindness. The picture is a map rather than a hardness proof --- but a map on which every known road runs through one pass, together with a proof that the pass is high.

